<script setup>
import axios from 'axios';
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import ConfirmDialog from '../../components/ConfirmDialog.vue';
import { useConfirmDialog } from '../../composables/useConfirmDialog';
import { useUnsavedForm } from '../../composables/useUnsavedForm';
import { useToast } from '../../composables/toastBus';

const props = defineProps({ workspace: { type: Object, required: true }, user: { type: Object, required: true } });
const emit = defineEmits(['updated']);
const { open: confirmOpen, options: confirmOptions, confirm: askConfirm, finish: finishConfirm } = useConfirmDialog();
const { success: notifySuccess } = useToast();
const route = useRoute(); const router = useRouter();
const tabs = [{ id: 'couple', label: 'Profil pasangan' }, { id: 'workspace', label: 'Workspace & acara' }, { id: 'access', label: 'Akses partner' }, { id: 'account', label: 'Akun saya' }, { id: 'privacy', label: 'Privasi & berbagi' }];
const initialTab = tabs.some((tab) => tab.id === route.query.tab) ? route.query.tab : 'couple';
const active = ref(initialTab); const members = ref([]); const loading = ref(true); const saving = ref(false); const error = ref(''); const inviteEmail = ref('');
const couple = reactive({ partner_one_name: props.workspace.partner_one_name || '', partner_two_name: props.workspace.partner_two_name || '' });
const workspace = reactive({ name: props.workspace.name || '', wedding_date: props.workspace.wedding_date || '', timezone: props.workspace.timezone || 'Asia/Jakarta' });
const profile = reactive({ name: props.user.name || '', email: props.user.email || '' });
const snapshots = ref({ couple: JSON.stringify(couple), workspace: JSON.stringify(workspace), account: JSON.stringify(profile) });
function activeForm(tab = active.value) { return tab === 'couple' ? couple : tab === 'workspace' ? workspace : tab === 'account' ? profile : null; }
const activeDirty = computed(() => { const form = activeForm(); return form ? JSON.stringify(form) !== snapshots.value[active.value] : false; });
function restoreActiveForm() { const form = activeForm(); if (form && snapshots.value[active.value]) Object.assign(form, JSON.parse(snapshots.value[active.value])); }
const settingsGuard = useUnsavedForm({ isOpen: computed(() => true), isDirty: activeDirty, confirm: askConfirm, onDiscard: restoreActiveForm, title: 'Perubahan pengaturan belum disimpan', message: 'Jika berpindah halaman sekarang, perubahan yang belum disimpan akan dibuang.' });
const timezones = ['Asia/Jakarta','Asia/Makassar','Asia/Jayapura','Asia/Singapore','Asia/Kuala_Lumpur','UTC'];
async function load() { loading.value = true; error.value = ''; try { members.value = (await axios.get(`/api/workspaces/${props.workspace.id}/members`)).data.members; } catch { error.value = 'Informasi akses belum berhasil dimuat.'; } finally { loading.value = false; } }
function notify(text) { notifySuccess(text); }
async function selectTab(id) { if (id === active.value || !await settingsGuard.requestClose()) return; active.value = id; error.value = ''; router.replace({ query: { ...route.query, tab: id === 'couple' ? undefined : id } }); }
watch(() => route.query.tab, (tab) => { active.value = tabs.some((item) => item.id === tab) ? tab : 'couple'; });
async function save() { saving.value = true; error.value = ''; try {
    if (active.value === 'couple' || active.value === 'workspace') { const { data } = await axios.patch(`/api/workspaces/${props.workspace.id}/settings`, { ...workspace, ...couple, wedding_date: workspace.wedding_date || null }); emit('updated', { ...props.user, workspaces: props.user.workspaces.map((w) => w.id === data.workspace.id ? data.workspace : w) }); }
    if (active.value === 'account') { const { data } = await axios.patch('/api/profile', profile); emit('updated', { ...props.user, ...data.user }); }
    if (activeForm()) snapshots.value[active.value] = JSON.stringify(activeForm());
    notify('Perubahan berhasil disimpan.');
} catch (e) { error.value = e.response?.data?.message || Object.values(e.response?.data?.errors || {}).flat()[0] || 'Perubahan belum berhasil disimpan.'; } finally { saving.value = false; } }
async function invite() { saving.value=true;error.value='';try { await axios.post(`/api/workspaces/${props.workspace.id}/invites`,{email:inviteEmail.value});inviteEmail.value='';notify('Undangan partner sudah dikirim.');await load(); } catch(e) { error.value=e.response?.data?.message || Object.values(e.response?.data?.errors||{}).flat()[0] || 'Undangan belum berhasil dikirim.'; } finally { saving.value=false; } }
async function removePartner(member) { if (!await askConfirm({ title: `Cabut akses ${member.name}?`, message: 'Partner ini tidak lagi dapat membuka data workspace pasangan.', confirmLabel: 'Cabut akses' })) return; try { await axios.delete(`/api/workspaces/${props.workspace.id}/members/${member.id}`); await load(); notify('Akses partner dicabut.'); } catch(e) { error.value=e.response?.data?.message || 'Akses partner belum berhasil dicabut.'; } }
async function cancelInvite() { if (!await askConfirm({ title: 'Batalkan undangan partner?', message: 'Tautan undangan tertunda tidak dapat digunakan setelah dibatalkan.', confirmLabel: 'Batalkan undangan' })) return; try { await axios.delete(`/api/workspaces/${props.workspace.id}/invitations/pending`); await load(); notify('Undangan tertunda dibatalkan.'); } catch { error.value='Undangan belum berhasil dibatalkan.'; } }
onMounted(load);
</script>

<template>
    <section class="settings-page">
        <header class="settings-head"><p class="eyebrow"><span class="eyebrow__dot"></span> RUANG KALIAN, DIATUR SESUAI KEBUTUHAN</p><h1>Pengaturan</h1><p>Kelola informasi pasangan, workspace, dan siapa yang dapat mengaksesnya.</p></header>
        <div class="settings-layout"><nav class="settings-nav" aria-label="Bagian pengaturan"><button v-for="tab in tabs" :key="tab.id" :class="{'is-active':active===tab.id}" :aria-current="active===tab.id?'page':undefined" @click="selectTab(tab.id)">{{ tab.label }}<FaIcon :icon="['fas','chevron-right']" /></button></nav>
            <section class="settings-panel">
                <p v-if="message" class="settings-success" role="status">{{ message }}</p><p v-if="error" class="settings-error" role="alert">{{ error }}</p><div v-if="loading" class="home-skeleton"><div class="skeleton-line skeleton-line--title"></div><div class="skeleton-block"></div></div>
                <div v-else class="settings-tab-stage">
                    <Transition name="tab-panel">
                        <div :key="active" class="settings-tab-content">
                <template v-if="active==='couple'"><div class="settings-section-head"><div><p class="eyebrow">PROFIL BERSAMA</p><h2>Nama pasangan</h2><p>Nama ini tampil di ruang persiapan dan undangan kalian.</p></div></div><form @submit.prevent="save"><label>Nama pasangan pertama<input v-model.trim="couple.partner_one_name" required maxlength="100" placeholder="Nama" /></label><label>Nama pasangan kedua<input v-model.trim="couple.partner_two_name" required maxlength="100" placeholder="Nama" /></label><button class="button button--primary" :disabled="saving">{{ saving?'Menyimpan…':'Simpan profil' }}</button></form></template>
                <template v-else-if="active==='workspace'"><div class="settings-section-head"><div><p class="eyebrow">RUANG PERSIAPAN</p><h2>Workspace & acara</h2><p>Atur nama workspace, tanggal pernikahan, dan zona waktu acara.</p></div></div><form @submit.prevent="save"><label>Nama workspace<input v-model.trim="workspace.name" required maxlength="120" /></label><label>Tanggal pernikahan<input v-model="workspace.wedding_date" type="date" /></label><label>Zona waktu<MotionSelect v-model="workspace.timezone"><option v-for="zone in timezones" :key="zone" :value="zone">{{ zone }}</option></MotionSelect></label><button class="button button--primary" :disabled="saving">{{ saving?'Menyimpan…':'Simpan workspace' }}</button></form></template>
                <template v-else-if="active==='access'"><div class="settings-section-head"><div><p class="eyebrow">KOLABORASI</p><h2>Akses partner</h2><p>Satu partner dapat bergabung untuk merencanakan bersama.</p></div></div><form class="invite-form" @submit.prevent="invite"><label>Email partner<input v-model.trim="inviteEmail" type="email" required placeholder="partner@email.com" /></label><button class="button button--primary" :disabled="saving">Kirim undangan</button></form><div v-for="member in members" :key="member.id" class="member-row"><span class="profile-chip__avatar">{{ member.name.slice(0,1) }}</span><span><strong>{{ member.name }}</strong><small>{{ member.role==='owner'?'Pemilik workspace':'Partner aktif' }}</small></span><button v-if="member.role==='partner'" class="button button--quiet danger" @click="removePartner(member)">Cabut akses</button></div><button class="text-button" @click="cancelInvite">Batalkan undangan tertunda</button></template>
                <template v-else-if="active==='account'"><div class="settings-section-head"><div><p class="eyebrow">AKUN PRIBADI</p><h2>Informasi akun</h2><p>Alamat email digunakan untuk masuk ke MENUJU dan menerima undangan.</p></div></div><form @submit.prevent="save"><label>Nama<input v-model.trim="profile.name" required maxlength="120" /></label><label>Email<input v-model.trim="profile.email" type="email" required maxlength="255" /></label><button class="button button--primary" :disabled="saving">Simpan akun</button></form></template>
                <template v-else><div class="settings-section-head"><div><p class="eyebrow">PRIVASI DATA</p><h2>Privasi & berbagi</h2><p>Data persiapan hanya dapat dilihat anggota aktif workspace. Undangan publik menampilkan informasi acara yang kalian pilih di Invitation Studio.</p></div></div><div class="privacy-card"><FaIcon :icon="['fas','lock']"/><div><strong>Data tamu dan keuangan bersifat privat</strong><p>Informasi kontak, daftar tamu, transaksi, dan tabungan tidak ditampilkan di undangan publik. Gunakan kontrol publish undangan untuk mengatur halaman yang dapat dilihat tamu.</p></div></div><RouterLink class="button button--quiet" to="/app/invitations">Kelola undangan publik</RouterLink></template>
                        </div>
                    </Transition>
                </div>
            </section>
        </div>
        <ConfirmDialog :open="confirmOpen" :title="confirmOptions.title" :message="confirmOptions.message" :confirm-label="confirmOptions.confirmLabel" @cancel="finishConfirm(false)" @confirm="finishConfirm(true)" />
    </section>
</template>

<style scoped>
.settings-page{max-width:1150px;margin:auto;padding:38px clamp(20px,4vw,56px) 70px;color:var(--text-primary)}.settings-head{margin-bottom:27px}.settings-head h1{font:500 clamp(42px,5vw,58px)/1 var(--font-display);margin:14px 0 9px}.settings-head>p:last-child{color:var(--text-secondary);font-size:14px}.settings-layout{display:grid;grid-template-columns:245px 1fr;gap:18px;align-items:start}.settings-nav,.settings-panel{background:var(--surface);border:1px solid var(--champagne);border-radius:15px}.settings-nav{padding:8px}.settings-nav button{width:100%;display:flex;justify-content:space-between;align-items:center;padding:13px;border:0;border-radius:8px;background:transparent;text-align:left;color:var(--text-secondary);font:13px var(--font-body);cursor:pointer;transition:background-color 180ms var(--motion-ease),color 180ms var(--motion-ease),transform 180ms var(--motion-ease-out)}.settings-nav button svg{font-size:10px;opacity:.55;transition:transform 180ms var(--motion-ease-out)}.settings-nav button.is-active{background:var(--surface-soft);color:var(--accent);font-weight:700}.settings-nav button.is-active svg{transform:translateX(2px)}.settings-nav button:active{transform:scale(.99)}.settings-panel{padding:clamp(20px,4vw,34px);min-height:420px}.settings-tab-stage{display:grid;min-width:0}.settings-tab-content{grid-area:1/1;min-width:0}.settings-section-head{display:flex;justify-content:space-between;border-bottom:1px solid var(--champagne);padding-bottom:18px;margin-bottom:20px}.settings-section-head h2{font:500 30px var(--font-display);margin:7px 0}.settings-section-head p:last-child{font-size:12px;color:var(--text-secondary);margin:0}.settings-panel form{max-width:530px;display:flex;flex-direction:column;gap:16px}.settings-panel form label{display:flex;flex-direction:column;gap:7px;font-size:12px;font-weight:600;color:var(--text-secondary)}.settings-panel input,.settings-panel select{height:43px;padding:0 12px;border:1px solid var(--border);border-radius:8px;background:white;font:13px var(--font-body)}.settings-panel form>.button{align-self:flex-end}.invite-form{display:grid!important;grid-template-columns:1fr auto;align-items:end;max-width:none!important;margin-bottom:20px}.member-row{display:flex;align-items:center;gap:11px;padding:13px 0;border-top:1px solid var(--champagne)}.member-row>span:nth-child(2){display:flex;flex:1;flex-direction:column;gap:4px}.member-row strong{font-size:12px}.member-row small{font-size:10px;color:var(--text-secondary)}.danger{color:#a44740}.text-button{padding:13px 0;border:0;background:none;color:var(--accent);font-size:11px;text-decoration:underline;cursor:pointer}.privacy-card{display:flex;gap:13px;padding:18px;background:#f2f3ed;border-radius:11px;margin:22px 0;color:var(--accent)}.privacy-card>svg{margin-top:3px}.privacy-card strong{font-size:13px}.privacy-card p{font-size:12px;line-height:1.65;color:var(--text-secondary)}.settings-success,.settings-error{padding:11px 13px;border-radius:8px;font-size:12px}.settings-success{background:#e9f2e6;color:#43623b}.settings-error{background:#fff0ee;color:#a13a34}@media(max-width:720px){.settings-page{padding:25px 16px 50px}.settings-layout{grid-template-columns:1fr}.settings-nav{display:flex;overflow:auto}.settings-nav button{width:auto;min-width:max-content}.settings-nav button svg{display:none}.invite-form{grid-template-columns:1fr!important}.member-row .button{font-size:10px;padding:9px}}
</style>
